#include <bits/stdc++.h>
using namespace std;
/* Function to find the ceiling of x using
binary search */
int ceilSearch(vector<int>& arr, int x) {
int lo = 0, hi = arr.size() - 1, res = -1;
while (lo <= hi) {
int mid = lo + (hi - lo) / 2;
if (arr[mid] < x)
lo = mid + 1;
else { // Potential ceiling found
res = mid;
hi = mid - 1;
}
}
return res;
}
